body:
Here's my self-contained test. I originally thought it had something to do with my type parameter being an abstract class, but I can't get it to work with a concrete class either.

``` java
import io.netty.bootstrap.Bootstrap;
import io.netty.bootstrap.ServerBootstrap;
import io.netty.buffer.ByteBuf;
import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelInitializer;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.channel.socket.nio.NioServerSocketChannel;
import io.netty.channel.socket.nio.NioSocketChannel;
import io.netty.handler.codec.ByteToMessageCodec;
import io.netty.handler.logging.LogLevel;
import io.netty.handler.logging.LoggingHandler;

public class ByteToMessageCodecTest {

    public static void main(String[] args) throws Exception {
        new ByteToMessageCodecTest();
    }


    public ByteToMessageCodecTest() throws Exception {
        new Server().start();
        new Client().start();
    }

    private static class Client implements Runnable {
        public void start() {
            new Thread(this).start();
        }

        @Override
        public void run() {
            try {
                Bootstrap b = new Bootstrap();
                try {
                    b.group(new NioEventLoopGroup())
                     .channel(NioSocketChannel.class)
                     .handler(new ChannelInitializer<SocketChannel>() {
                         @Override
                         protected void initChannel(SocketChannel socketChannel) throws Exception {
                             //                          socketChannel.pipeline().addLast(new AbstractBarByteToMessageCodec());
                             socketChannel.pipeline().addLast(new ConcreteFooByteToMessageCodec());
                         }
                     });

                    ChannelFuture f = b.connect("localhost", 0xAF12).sync();
                    f.channel().write(new BarImpl(1));
                } finally {
                    b.shutdown();
                }
            } catch (Exception e) {
                System.err.println(e);
            }
        }
    }

    private static class Server implements Runnable {
        public void start() {
            new Thread(this).start();
        }

        @Override
        public void run() {
            ServerBootstrap b = new ServerBootstrap();
            try {
                b.group(new NioEventLoopGroup(), new NioEventLoopGroup())
                 .channel(NioServerSocketChannel.class)
                 .handler(new LoggingHandler(LogLevel.INFO))
                 .childHandler(new ChannelInitializer<SocketChannel>() {
                     @Override
                     public void initChannel(SocketChannel socketChannel) throws Exception {
                         socketChannel.pipeline().addLast(new LoggingHandler(LogLevel.INFO));
                         //                      socketChannel.pipeline().addLast(new AbstractBarByteToMessageCodec());
                         socketChannel.pipeline().addLast(new ConcreteFooByteToMessageCodec());
                     }
                 });

                ChannelFuture f = b.bind(0xAF12).sync();
                f.channel().closeFuture().sync();
            } catch (Exception e) {
                System.out.println(e);
            } finally {
                b.shutdown();
            }
        }
    }


    public static class ConcreteFoo {
        private final int foo;

        public ConcreteFoo(int foo) {
            this.foo = foo;
        }

        public int getFoo() {
            return foo;
        }
    }

    public static abstract class AbstractBar {
        private final int bar;

        protected AbstractBar(int bar) {
            this.bar = bar;
        }

        public int getBar() {
            return bar;
        }
    }

    public static class BarImpl extends AbstractBar {
        public BarImpl(int bar) {
            super(bar);
        }
    }

    private static class ConcreteFooByteToMessageCodec extends ByteToMessageCodec<ConcreteFoo> {
        @Override
        protected void encode(ChannelHandlerContext channelHandlerContext, ConcreteFoo foo, ByteBuf byteBuf) throws Exception {
            byteBuf.writeInt(foo.getFoo());
        }

        @Override
        protected Object decode(ChannelHandlerContext channelHandlerContext, ByteBuf byteBuf) throws Exception {
            int foo = byteBuf.readInt();
            return new ConcreteFoo(foo);
        }
    }

    private static class AbstractBarByteToMessageCodec extends ByteToMessageCodec<AbstractBar> {
        @Override
        protected void encode(ChannelHandlerContext channelHandlerContext, AbstractBar abstractBar, ByteBuf byteBuf) throws Exception {
            byteBuf.writeInt(abstractBar.getBar());
        }

        @Override
        protected Object decode(ChannelHandlerContext channelHandlerContext, ByteBuf byteBuf) throws Exception {
            int bar = byteBuf.readInt();
            return new BarImpl(bar);
        }
    }

}
